package org.padtv.glprobe;
import android.opengl.*;
import android.app.Activity;
import android.os.Bundle;
import java.nio.*;
import java.io.*;
public class GLActivity extends Activity {
 private static int shader(int type,String source){int id=GLES20.glCreateShader(type);GLES20.glShaderSource(id,source);GLES20.glCompileShader(id);int[] status=new int[1];GLES20.glGetShaderiv(id,GLES20.GL_COMPILE_STATUS,status,0);if(status[0]!=1)throw new AssertionError(GLES20.glGetShaderInfoLog(id));return id;}
 protected void onCreate(Bundle state){super.onCreate(state);EGLDisplay display=EGL14.eglGetDisplay(0);int[] version=new int[2];if(!EGL14.eglInitialize(display,version,0,version,1))throw new AssertionError("EGL initialize");EGLConfig[] configs=new EGLConfig[1];int[] count=new int[1];if(!EGL14.eglChooseConfig(display,new int[]{EGL14.EGL_RENDERABLE_TYPE,4,EGL14.EGL_SURFACE_TYPE,1,EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_NONE},0,configs,0,1,count,0)||count[0]!=1)throw new AssertionError("EGL configs");EGLContext context=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);EGLSurface surface=EGL14.eglCreatePbufferSurface(display,configs[0],new int[]{EGL14.EGL_WIDTH,64,EGL14.EGL_HEIGHT,64,EGL14.EGL_NONE},0);if(!EGL14.eglMakeCurrent(display,surface,surface,context))throw new AssertionError("EGL current");
  try{GLES20.glViewport(0,0,64,64);GLES20.glClearColor(0,0,1,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);int vertex=shader(GLES20.GL_VERTEX_SHADER,"attribute vec2 pos;void main(){gl_Position=vec4(pos,0.0,1.0);}");int fragment=shader(GLES20.GL_FRAGMENT_SHADER,"precision mediump float;void main(){gl_FragColor=vec4(1.0,0.0,0.0,1.0);}");int program=GLES20.glCreateProgram();GLES20.glAttachShader(program,vertex);GLES20.glAttachShader(program,fragment);GLES20.glLinkProgram(program);int[] linked=new int[1];GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,linked,0);if(linked[0]!=1)throw new AssertionError(GLES20.glGetProgramInfoLog(program));GLES20.glUseProgram(program);int[] buffer=new int[1];GLES20.glGenBuffers(1,buffer,0);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,buffer[0]);FloatBuffer vertices=ByteBuffer.allocateDirect(24).order(ByteOrder.nativeOrder()).asFloatBuffer();vertices.put(new float[]{-0.8f,-0.8f,0.8f,-0.8f,0,0.8f}).rewind();GLES20.glBufferData(GLES20.GL_ARRAY_BUFFER,24,vertices,GLES20.GL_STATIC_DRAW);int location=GLES20.glGetAttribLocation(program,"pos");GLES20.glVertexAttribPointer(location,2,GLES20.GL_FLOAT,false,8,0);GLES20.glEnableVertexAttribArray(location);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,3);GLES20.glFinish();ByteBuffer pixels=ByteBuffer.allocateDirect(64*64*4);GLES20.glReadPixels(0,0,64,64,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixels);if(GLES20.glGetError()!=0)throw new AssertionError("GL error");byte[] data=new byte[pixels.capacity()];pixels.get(data);try(FileOutputStream out=openFileOutput("triangle.rgba",0)){out.write(data);}catch(IOException e){throw new IllegalStateException(e);}System.out.println("REAL_EGL_GLES_SHADER_OK "+GLES20.glGetString(GLES20.GL_RENDERER));GLES20.glDeleteShader(vertex);GLES20.glDeleteShader(fragment);GLES20.glDeleteProgram(program);
  }finally{EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);EGL14.eglDestroySurface(display,surface);EGL14.eglDestroyContext(display,context);EGL14.eglTerminate(display);}
 }
}
